<?php
require dirname(__DIR__).'/bootstrap.php';
use AranduGo\Auth;use AranduGo\SiteRepository;use AranduGo\Support;
Auth::requireLogin();if(!class_exists('ZipArchive'))exit('La extensión ZIP de PHP no está habilitada.');$file=Support::basePath('storage/backups/arandu-go-'.date('Ymd-His').'.zip');$zip=new ZipArchive();if($zip->open($file,ZipArchive::CREATE|ZipArchive::OVERWRITE)!==true)exit('No se pudo crear el respaldo.');$zip->addFromString('contenido/draft.json',json_encode(SiteRepository::draft(),JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES));$zip->addFromString('contenido/published.json',json_encode(SiteRepository::published(),JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES));$root=Support::basePath('uploads');$iterator=new RecursiveIteratorIterator(new RecursiveDirectoryIterator($root,FilesystemIterator::SKIP_DOTS));foreach($iterator as $item){if(!$item->isFile()||str_starts_with($item->getFilename(),'.'))continue;$relative='uploads/'.substr($item->getPathname(),strlen($root)+1);$zip->addFile($item->getPathname(),$relative);}$zip->close();header('Content-Type: application/zip');header('Content-Disposition: attachment; filename="'.basename($file).'"');header('Content-Length: '.filesize($file));readfile($file);unlink($file);exit;
